create table if not exists public.sales_order (
  id bigint generated by default as identity primary key,
  company_id bigint not null,
  quotation_id bigint not null references public.quotation(id),
  customer_id bigint not null,
  code varchar(50) not null,
  issue_date date not null default current_date,
  requested_delivery_date date,
  status varchar(40) not null default 'PENDING_MANUFACTURING',
  reference text,
  notes text,
  net_amount numeric(15,2) not null default 0,
  discount_amount numeric(15,2) not null default 0,
  tax_amount numeric(15,2) not null default 0,
  total_amount numeric(15,2) not null default 0,
  billing_address_street text,
  billing_address_city text,
  billing_address_postal_code text,
  billing_address_region text,
  installation_address_street text,
  installation_address_city text,
  installation_address_postal_code text,
  installation_address_region text,
  contact_id bigint,
  contact_name text,
  contact_email text,
  contact_phone text,
  commercial_id bigint,
  warehouse_id bigint,
  payment_method_id bigint,
  payment_term_id bigint,
  measurement_id bigint,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint sales_order_company_code_uk unique(company_id, code),
  constraint sales_order_quotation_uk unique(quotation_id),
  constraint sales_order_status_ck check (status in ('PENDING_MANUFACTURING','PREPARED','CONFECTIONED','MANUFACTURED','INSTALLED','CANCELLED'))
);
create table if not exists public.sales_order_line (
  id bigint generated by default as identity primary key,
  sales_order_id bigint not null references public.sales_order(id) on delete cascade,
  quotation_line_id bigint,
  line_no integer not null,
  product_id bigint,
  description text,
  quantity numeric(15,4) not null default 0,
  unit_price numeric(15,4) not null default 0,
  discount_percent numeric(9,4) not null default 0,
  tax_percent numeric(9,4) not null default 0,
  net_amount numeric(15,2) not null default 0,
  tax_amount numeric(15,2) not null default 0,
  total_amount numeric(15,2) not null default 0,
  specific_data jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint sales_order_line_no_uk unique(sales_order_id, line_no)
);
create index if not exists ix_sales_order_company on public.sales_order(company_id, issue_date desc);
create index if not exists ix_sales_order_customer on public.sales_order(customer_id);
create index if not exists ix_sales_order_quotation on public.sales_order(quotation_id);
create index if not exists ix_sales_order_line_order on public.sales_order_line(sales_order_id, line_no);
create or replace function public.generate_sales_order_code(p_company_id bigint) returns varchar language plpgsql as $$ declare y text := to_char(current_date, 'YYYY'); n integer; begin select coalesce(max(nullif(regexp_replace(code, '^PED-' || y || '/', ''), '')::integer), 0) + 1 into n from public.sales_order where company_id = p_company_id and code like 'PED-' || y || '/%'; return 'PED-' || y || '/' || lpad(n::text, 3, '0'); end; $$;
create or replace function public.create_sales_order_from_quotation(p_quotation_id bigint) returns bigint language plpgsql security invoker as $$ declare q record; o_id bigint; l record; v_code varchar; v_company bigint; begin select * into q from public.quotation where id = p_quotation_id; if not found then raise exception 'Presupuesto no encontrado'; end if; if q.status <> 'ACCEPTED' then raise exception 'Solo se puede crear un pedido desde un presupuesto aceptado'; end if; if q.customer_id is null then raise exception 'El presupuesto debe tener cliente antes de crear el pedido'; end if; if exists(select 1 from public.sales_order where quotation_id = p_quotation_id) then select id into o_id from public.sales_order where quotation_id = p_quotation_id; return o_id; end if; v_company := q.company_id; v_code := public.generate_sales_order_code(v_company); insert into public.sales_order (company_id, quotation_id, customer_id, code, issue_date, requested_delivery_date, status, reference, notes, net_amount, discount_amount, tax_amount, total_amount, billing_address_street, billing_address_city, billing_address_postal_code, billing_address_region, installation_address_street, installation_address_city, installation_address_postal_code, installation_address_region, contact_id, contact_name, contact_email, contact_phone, commercial_id, warehouse_id, payment_method_id, payment_term_id, measurement_id) values (q.company_id, q.id, q.customer_id, v_code, current_date, null, 'PENDING_MANUFACTURING', q.reference, q.notes, q.net_amount, q.discount_amount, q.tax_amount, q.total_amount, q.billing_address_street, q.billing_address_city, q.billing_address_postal_code, q.billing_address_region, q.installation_address_street, q.installation_address_city, q.installation_address_postal_code, q.installation_address_region, q.contact_id, q.contact_name, q.contact_email, q.contact_phone, q.commercial_id, q.warehouse_id, q.payment_method_id, q.payment_term_id, q.measurement_id) returning id into o_id; for l in select * from public.quotation_line where quotation_id = p_quotation_id order by line_no loop insert into public.sales_order_line (sales_order_id, quotation_line_id, line_no, product_id, description, quantity, unit_price, discount_percent, tax_percent, net_amount, tax_amount, total_amount, specific_data) values (o_id, l.id, l.line_no, l.product_id, l.description, l.quantity, l.unit_price, l.discount_percent, l.tax_percent, l.net_amount, l.tax_amount, l.total_amount, coalesce(l.specific_data, '{}'::jsonb)); end loop; return o_id; end; $$;
alter table public.sales_order enable row level security;
alter table public.sales_order_line enable row level security;
create policy sales_order_company_select on public.sales_order for select using (company_id = (select company_id from public.user_account where auth_user_id = auth.uid()));
create policy sales_order_company_insert on public.sales_order for insert with check (company_id = (select company_id from public.user_account where auth_user_id = auth.uid()));
create policy sales_order_company_update on public.sales_order for update using (company_id = (select company_id from public.user_account where auth_user_id = auth.uid())) with check (company_id = (select company_id from public.user_account where auth_user_id = auth.uid()));
create policy sales_order_company_delete on public.sales_order for delete using (company_id = (select company_id from public.user_account where auth_user_id = auth.uid()));
create policy sales_order_line_company_select on public.sales_order_line for select using (exists(select 1 from public.sales_order o where o.id = sales_order_id and o.company_id = (select company_id from public.user_account where auth_user_id = auth.uid())));
create policy sales_order_line_company_insert on public.sales_order_line for insert with check (exists(select 1 from public.sales_order o where o.id = sales_order_id and o.company_id = (select company_id from public.user_account where auth_user_id = auth.uid())));
create policy sales_order_line_company_update on public.sales_order_line for update using (exists(select 1 from public.sales_order o where o.id = sales_order_id and o.company_id = (select company_id from public.user_account where auth_user_id = auth.uid()))) with check (exists(select 1 from public.sales_order o where o.id = sales_order_id and o.company_id = (select company_id from public.user_account where auth_user_id = auth.uid())));
create policy sales_order_line_company_delete on public.sales_order_line for delete using (exists(select 1 from public.sales_order o where o.id = sales_order_id and o.company_id = (select company_id from public.user_account where auth_user_id = auth.uid())));
grant execute on function public.create_sales_order_from_quotation(bigint) to authenticated;
